pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(address acct, uint256 id) public {
        id = bound(id, 0, 1000);

        bool ok;
        try c.balanceOf(acct, id) returns (uint256) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == (acct != address(0)));
    }
}
